
import cadquery as cq

# Parameters
bracket_length = 80.0
bracket_width = 40.0
bracket_thickness = 8.0
rib_height = 20.0
rib_radius = 6.0
hole_diameter = 6.0
hole_offset_x = 15.0
hole_offset_y = 10.0
chamfer_size = 1.0
slot_width = 4.0
slot_length = 12.0
slot_offset_y = 5.0
pocket_depth = 3.0
pocket_margin = 5.0
mount_hole_spacing = 20.0

# Base plate
base = (
    cq.Workplane("XY")
    .rect(bracket_length, bracket_width)
    .extrude(bracket_thickness)
)

# Side rib generated by revolve
rib_profile = (
    cq.Workplane("YZ")
    .workplane(offset=bracket_width / 2)
    .rect(rib_radius, rib_height, centered=False)
    .revolve(180, (0, 0, 0), (1, 0, 0))
)

# Union rib with base and apply chamfer on vertical free edges
bracket_chamfered = base.union(rib_profile).edges("|Z").chamfer(chamfer_size)

# Through-hole (bolt clearance)
with_hole = (
    bracket_chamfered
    .faces('>Z')
    .workplane()
    .center(hole_offset_x - bracket_length / 2, hole_offset_y - bracket_width / 2)
    .hole(hole_diameter)
)

# Slot on top surface for cable routing
with_slot = (
    with_hole
    .faces('>Z')
    .workplane()
    .center(0, slot_offset_y - bracket_width / 2)
    .rect(slot_length, slot_width)
    .cutBlind(-bracket_thickness / 2)
)

# Underside pocket for weight reduction
with_pocket = (
    with_slot
    .faces('<Z')
    .workplane()
    .rect(bracket_length - 2 * pocket_margin, bracket_width - 2 * pocket_margin)
    .cutBlind(-pocket_depth)
)

# Pattern of four mounting holes near corners
mount_spacing_x = bracket_length / 2 - pocket_margin
mount_spacing_y = bracket_width / 2 - pocket_margin
with_mounts = (
    with_pocket
    .faces('>Z')
    .workplane()
    .pushPoints([
        (-mount_spacing_x, -mount_spacing_y),
        ( mount_spacing_x, -mount_spacing_y),
        (-mount_spacing_x,  mount_spacing_y),
        ( mount_spacing_x,  mount_spacing_y),
    ])
    .hole(hole_diameter)
)

# Small internal fillet for safety on a corner edge
final = with_mounts.edges("|Z and <Y").fillet(0.5)

result = final
